local decrypted = {}
local idx = 1
for cc in hex:gmatch("%x%x") do
    local val = tonumber(cc, 16) - key
    if val < 0 then val = val + 256 end
    decrypted[idx] = string.char(val)
    idx = idx + 1
end

local _load = loadstring or load
if not _load then
    error("Erro: Seu executor nao suporta loadstring/load.")
end

local fn, err = _load(table.concat(decrypted), "=ia.lua")
if fn then
    return fn(...)
else
    error("Execution failed: " .. tostring(err))
end
